CREATE TABLE IF NOT EXISTS lattis_fakturownia_invoice (external_id char(36) PRIMARY KEY, gross_minor bigint NOT NULL CHECK (gross_minor > 0), currency char(3) NOT NULL CHECK (currency = 'PLN'), payload_sealed text NOT NULL, payload_digest char(64) NOT NULL, created_by varchar(191) NOT NULL, status varchar(20) NOT NULL CHECK (status IN ('QUEUED','IN_FLIGHT','NEEDS_REVIEW','BLOCKED','ISSUED')), fakturownia_id bigint NULL UNIQUE, invoice_number varchar(100) NULL, last_error varchar(100) NULL, attempt_count int NOT NULL DEFAULT 0, attempted_at datetime(3) NULL, created_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY lattis_fakturownia_invoice_status (status,created_at));
